--liquibase formatted sql

--changeset codex:034-deterministic-planner
ALTER TABLE training_proposals DROP CONSTRAINT IF EXISTS training_proposals_source_ai;
ALTER TABLE training_proposals DROP CONSTRAINT IF EXISTS training_proposals_source_check;
ALTER TABLE training_proposals ALTER COLUMN source TYPE VARCHAR(16);
ALTER TABLE training_proposals ADD CONSTRAINT training_proposals_source_check
  CHECK (source IN ('AI','COACH','RULE_BASED'));

ALTER TABLE calendar_draft_jobs DROP CONSTRAINT calendar_draft_jobs_state_check;
ALTER TABLE calendar_draft_jobs ADD CONSTRAINT calendar_draft_jobs_state_check
  CHECK(state IN ('QUEUED','RUNNING','READY','FAILED','SUPERSEDED','STALE','EXPIRED','IMPOSSIBLE'));
ALTER TABLE calendar_draft_jobs ADD COLUMN protocol INTEGER NOT NULL DEFAULT 1 CHECK (protocol IN (1,2));
ALTER TABLE calendar_draft_jobs ADD COLUMN variant INTEGER NOT NULL DEFAULT 0 CHECK (variant >= 0);
ALTER TABLE calendar_draft_jobs ADD COLUMN execution_snapshot JSONB;

CREATE TABLE planner_builtin_exercise_mappings (
  exercise_id UUID PRIMARY KEY,
  movement_class VARCHAR(32) NOT NULL,
  roles JSONB NOT NULL,
  supported_goals JSONB NOT NULL,
  exercise_type VARCHAR(16) NOT NULL,
  equipment_ids JSONB NOT NULL,
  revision BIGINT NOT NULL DEFAULT 1 CHECK (revision > 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now()
);
CREATE TABLE planner_owner_exercise_mappings (
  owner_id UUID NOT NULL REFERENCES users(id) ON DELETE CASCADE,
  exercise_id UUID NOT NULL,
  movement_class VARCHAR(32) NOT NULL,
  roles JSONB NOT NULL,
  supported_goals JSONB NOT NULL,
  exercise_type VARCHAR(16) NOT NULL,
  equipment_ids JSONB NOT NULL,
  revision BIGINT NOT NULL DEFAULT 1 CHECK (revision > 0),
  created_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  updated_at TIMESTAMPTZ NOT NULL DEFAULT now(),
  PRIMARY KEY(owner_id, exercise_id)
);
CREATE INDEX planner_owner_exercise_mappings_exercise
  ON planner_owner_exercise_mappings(exercise_id);


ALTER TABLE calendar_draft_jobs ADD COLUMN raw_request BYTEA;
ALTER TABLE calendar_draft_jobs ADD COLUMN request_kind VARCHAR(16) NOT NULL DEFAULT 'CREATE';
ALTER TABLE calendar_draft_jobs ADD COLUMN base_proposal_id UUID;

-- Reviewed UUIDs from CanonicalExerciseRegistry and explicit CanonicalEquipmentRequirements.
-- Seed missing classification only; operator edits survive every deployment.
ON CONFLICT(exercise_id) DO NOTHING;
